DECLARE permitted boolean; a hotel_stripe_connect_private.accounts%rowtype; platform boolean; attestation text;
BEGIN
 PERFORM public.hotel_v2_h3_2a_require_partner_hotel_access(p_partner_id,p_hotel_id,null,false);
 platform:=(hotels_lifecycle_private.safe_state()->'feature_flags'->>'hotel_stripe_connect_enabled')::boolean;
 permitted:=EXISTS(SELECT 1 FROM public.partner_users WHERE partner_id=p_partner_id AND user_id=auth.uid() AND role='owner')
  AND (hotel_stripe_connect_private.authorization_state(p_partner_id)->>'enabled')::boolean;
 PERFORM hotels_stripe_dto_private.predecessor_source('hotels_lifecycle_private.partner_connection(uuid,uuid)'::regprocedure);
 PERFORM hotels_stripe_dto_private.assert_exact();
 SELECT coalesce((SELECT CASE
  WHEN contract_version IS DISTINCT FROM 'hotels_standard_connect_server_v1' OR ready IS NOT TRUE THEN 'NOT_READY'
  WHEN checked_at<=statement_timestamp()-interval '15 minutes' THEN 'STALE'
  ELSE 'READY' END FROM hotels_lifecycle_private.stripe_readiness
  ORDER BY checked_at DESC,request_id DESC LIMIT 1),'MISSING') INTO attestation;
 SELECT * INTO a FROM hotel_stripe_connect_private.accounts WHERE partner_id=p_partner_id;
 RETURN jsonb_build_object('contract_version','hotels_partner_stripe_capability_v1','partner_id',p_partner_id,'hotel_id',p_hotel_id,
 'platform_enabled',platform,'onboarding_authorized',permitted,'account_status',coalesce(a.status,'NOT_CONNECTED'),
 'checked_at',a.checked_at,'platform_ready',attestation='READY','attestation_status',attestation,'can_connect',platform AND permitted AND (a.partner_id IS NULL OR a.status='ONBOARDING_INCOMPLETE'));
END

declare
  v_membership jsonb;
  v_partner_user_id uuid;
  v_role text;
  v_assignment_id uuid;
  v_allowed boolean;
begin
  if p_hotel_id is null then
    raise exception using errcode = '42501', message = 'hotels_v2_h3_2a_partner_access_denied';
  end if;

  v_membership := public.hotel_v2_h3_2a_require_partner_membership(p_partner_id);
  v_partner_user_id := (v_membership->>'partner_user_id')::uuid;
  v_role := v_membership->>'role';

  select assignment.id into v_assignment_id
  from public.partner_resources assignment
  where assignment.partner_id = p_partner_id
    and assignment.resource_type = 'hotels'
    and assignment.resource_id = p_hotel_id
    and (
      v_role = 'owner'
      or exists (
        select 1
        from public.partner_user_resources user_scope
        where user_scope.partner_user_id = v_partner_user_id
          and user_scope.resource_type = 'hotels'
          and user_scope.resource_id = p_hotel_id
      )
    );

  if v_assignment_id is null then
    raise exception using errcode = '42501', message = 'hotels_v2_h3_2a_partner_access_denied';
  end if;

  if p_owner_only and v_role <> 'owner' then
    raise exception using errcode = '42501', message = 'hotels_v2_h3_2a_partner_access_denied';
  end if;

  if p_capability is not null then
    if not (p_capability = any(public.hotel_v2_h3_2a_capability_catalog())) then
      raise exception using errcode = '22023', message = 'hotels_v2_h3_2a_invalid_capability';
    end if;

    select case p_capability
      when 'edit_property_content' then permission.edit_property_content
      when 'edit_property_photos' then permission.edit_property_photos
      when 'edit_room_content' then permission.edit_room_content
      when 'edit_room_photos' then permission.edit_room_photos
      when 'create_rooms' then permission.create_rooms
      when 'edit_room_structure' then permission.edit_room_structure
      when 'manage_prices' then permission.manage_prices
      when 'manage_availability' then permission.manage_availability
      when 'process_bookings' then permission.process_bookings
      when 'request_booking_changes' then permission.request_booking_changes
      when 'view_payment_status' then permission.view_payment_status
      when 'initiate_stripe_onboarding' then permission.initiate_stripe_onboarding
      else false
    end into v_allowed
    from public.hotel_partner_hotel_permissions permission
    where permission.assignment_id = v_assignment_id
      and permission.partner_id = p_partner_id
      and permission.hotel_id = p_hotel_id;

    if not coalesce(v_allowed, false)
       or (p_capability = 'initiate_stripe_onboarding' and v_role <> 'owner') then
      raise exception using errcode = '42501', message = 'hotels_v2_h3_2a_partner_access_denied';
    end if;
  end if;

  if (select count(*) from public.site_settings) <> 1
     or exists (
    select 1 from public.site_settings setting
    where setting.id <> 1 or (
      not hotels_lifecycle_private.predecessor_flag_exact('hotel_rooms_v2_enabled',setting.hotel_rooms_v2_enabled)
      or false
      or setting.hotel_instant_booking_enabled
      or not hotels_lifecycle_private.predecessor_flag_exact('hotel_stripe_connect_enabled',setting.hotel_stripe_connect_enabled)
    )
  ) then
    raise exception using errcode = '55000', message = 'hotels_v2_h3_2a_public_activation_guard';
  end if;

  return v_assignment_id;
end

declare v_assignment uuid; v_membership jsonb; v_permission jsonb;
begin
  if not public.hotel_v2_h3_2b_flags_off() then
    raise exception using errcode='55000',message='hotels_v2_h3_2b_public_activation_guard';
  end if;
  if not exists(select 1 from public.hotels hotel
      where hotel.id=p_hotel_id and hotel.architecture_version='legacy') then
    raise exception using errcode='55000',message='hotels_v2_h3_2b_legacy_architecture_guard';
  end if;
  v_assignment:=public.hotel_v2_h3_2a_require_partner_hotel_access(
    p_partner_id,p_hotel_id,p_capability,false);
  v_membership:=public.hotel_v2_h3_2a_require_partner_membership(p_partner_id);
  v_permission:=public.hotel_v2_h3_2a_permissions_snapshot(v_assignment);
  return jsonb_build_object('assignment_id',v_assignment,'role',v_membership->>'role',
    'permission_version',(v_permission->>'version')::bigint,
    'has_mutation_capability',(v_permission->>'has_mutation_capability')::boolean,
    'capabilities',v_permission->'capabilities');
end
